using Confectory.Core;
using Confectory.Tests;
using System.Text.Json.Nodes;

var rows=new JsonArray();
void Check(bool value,string why){if(!value)throw new Exception(why);}
void Record(string name,object result){rows.Add(new JsonObject{["name"]=name,["passed"]=true,["result"]=System.Text.Json.JsonSerializer.SerializeToNode(result)});Console.WriteLine("PASS "+name);}
string Run(Fixture fixture,string target,string expected,bool graph){var built=new Builder(fixture.Project,target).Build();var result=Processes.Run(built["run"]!.AsArray().Select(x=>x!.ToString()).ToArray(),timeoutSeconds:30);Check(result.ExitCode==0&&result.Stdout.Trim()==expected,result.Stdout+result.Stderr);bool present=built["blueprints"]?["Provider::ValueBody"] is not null;Check(present==graph,"selected source kind differs");return result.Stdout.Trim();}
JsonObject Graph(string source,string[]? imports=null){string feature="function Api::Value (int n) -> int {}";return new JsonObject{["schema"]=1,["profile"]=FeatureBlueprint.Profile,["feature"]="Api::Value",["contractHash"]=FeatureBlueprint.ContractHash(new Parser(feature,"<review-contract>").ParseElement()),["entry"]="body",["nodes"]=new JsonArray(new JsonObject{["id"]="body",["kind"]="code",["intent"]="Explicit owned compatibility probe",["control"]="next",["signature"]=new JsonObject{["args"]=new JsonArray(new JsonObject{["type"]="int",["name"]="n"}),["return"]="int"},["arguments"]=new JsonObject{["n"]=new JsonObject{["input"]="n"}},["imports"]=new JsonArray((imports??[]).Select(x=>(JsonNode)JsonValue.Create(x)!).ToArray()),["implementation"]="body.node.json"}),["edges"]=new JsonArray(new JsonObject{["from"]="body",["port"]="next",["to"]="exit:return"}),["exits"]=new JsonObject{["return"]=new JsonObject{["node"]="body"}}};}
void WriteGraph(Fixture fixture,string source,bool imported=false){var graph=Graph(source,imported?["Api::Double"]:[]);var request=new JsonObject{["operation"]="featureBlueprintNodes",["featureSource"]="function Api::Value (int n) -> int {}",["graph"]=graph.DeepClone(),["featureContracts"]=new JsonObject{["Api::Double"]="function Api::Double (int n) -> int {}"}};var metadata=FeatureBlueprint.Execute(request);Check(metadata["state"]!.ToString()=="node-definitions",metadata.ToJsonString());fixture.Body("Provider","review.graph.json",graph.ToJsonString());fixture.Body("Provider","body.node.json",new JsonObject{["schema"]=1,["node"]="body",["definitionHash"]=metadata["nodes"]![0]!["definitionHash"]!.DeepClone(),["source"]=source}.ToJsonString());}
string Hash(string path)=>JsonData.HashBytes(File.ReadAllBytes(path));
using(var f=new Fixture()){
 string fn=Hash(Path.Combine(f.Packs["Api"].Root,"Value.celem")),common=Hash(Path.Combine(f.Packs["Provider"].Root,"value.csbody")),linux=Hash(Path.Combine(f.Packs["Provider"].Root,"value_linux.csbody"));
 Record("legacy-body-target-selection",new{portable=Run(f,"portable","5",false),linux=Run(f,"linux","32",false)});
 WriteGraph(f,"return n + 100;");f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value (int n) -> int {blueprint common \"review.graph.json\";body linux \"value_linux.csbody\";}");f.Sync();
 Record("mixed-common-blueprint-linux-legacy",new{portable=Run(f,"portable","102",true),linux=Run(f,"linux","32",false)});
 string duplicateCode="";try{new Parser("implementation Provider::ValueBody for Api::Value (int n) -> int {body common \"value.csbody\";blueprint common \"review.graph.json\";}","<duplicate-review>").ParseElement();}catch(BuildError error){duplicateCode=error.Diagnostic.Code;}Check(duplicateCode=="DUPLICATE_DECLARATION",duplicateCode);Record("same-target-body-blueprint-refused",new{code=duplicateCode});
 f.Add("Provider","implementation","ParentBody","implementation Provider::ParentBody for Api::Value (int n) -> int {body common \"value.csbody\";body linux \"value_linux.csbody\";}");f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value (int n) -> int extends Provider::ParentBody {blueprint common \"review.graph.json\";}");f.Sync();
 Record("same-function-implementation-inheritance-keeps-target-origin",new{portable=Run(f,"portable","102",true),linux=Run(f,"linux","32",false)});
 Check(fn==Hash(Path.Combine(f.Packs["Api"].Root,"Value.celem"))&&common==Hash(Path.Combine(f.Packs["Provider"].Root,"value.csbody"))&&linux==Hash(Path.Combine(f.Packs["Provider"].Root,"value_linux.csbody")),"legacy function/body bytes changed");Record("mixed-and-inherited-probes-preserve-legacy-bytes",new{function=fn,common,linux});
}
using(var f=new Fixture()){
 f.Add("Api","function","Double","function Api::Double (int n) -> int {}");f.Add("Provider","implementation","DoubleBody","implementation Provider::DoubleBody for Api::Double (int n) -> int {body common \"double.csbody\";}");f.Body("Provider","double.csbody","return n * 2;");f.Add("Provider","implementation","TripleBody","implementation Provider::TripleBody for Api::Double (int n) -> int {body common \"triple.csbody\";}");f.Body("Provider","triple.csbody","return n * 3;");f.Add("Provider","object","DoubleScope","object Provider::DoubleScope {provide Api::Double with Provider::DoubleBody;}");f.Main("provide Api::Value with Provider::ValueBody;provide Api::Double with Provider::TripleBody;");
 string oldBody="return calls.Double.Invoke(n);";f.Body("Provider","value.csbody",oldBody);f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value (int n) -> int {import Api::Double as Double (int) -> int in Provider::DoubleScope;body common \"value.csbody\";}");f.Sync();string original=Hash(Path.Combine(f.Packs["Provider"].Root,"value.csbody"));Record("legacy-typed-import-explicit-scope",new{output=Run(f,"portable","4",false)});
 WriteGraph(f,oldBody);f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value (int n) -> int {import Api::Double as Double (int) -> int in Provider::DoubleScope;blueprint common \"review.graph.json\";}");f.Sync();string diagnostic="",errorCode="";try{new Builder(f.Project,"portable").Build();}catch(BuildError error){diagnostic=error.ToString();errorCode=error.Diagnostic.Code;}Check(errorCode=="TARGET_FAILURE"&&diagnostic.Contains("CS8422",StringComparison.Ordinal),diagnostic);Record("blind-legacy-calls-body-copy-is-not-compatible",new{code=errorCode,compiler="CS8422",reason="A static node cannot capture the original implementation calls field."});
 string alias=FeatureBlueprint.ImportAlias("Api::Double");WriteGraph(f,"return "+alias+".Invoke(n);",true);f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value (int n) -> int {import Api::Double as "+alias+" (int) -> int in Provider::DoubleScope;blueprint common \"review.graph.json\";}");f.Sync();Record("explicit-node-import-rewrite-preserves-scope",new{output=Run(f,"portable","4",true)});
 f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value (int n) -> int {import Api::Double as "+alias+" (int) -> int;blueprint common \"review.graph.json\";}");f.Sync();Record("dropping-existing-scope-changes-provider",new{output=Run(f,"portable","6",true),originalOutput="4"});Check(original==Hash(Path.Combine(f.Packs["Provider"].Root,"value.csbody")),"original legacy source was copied over");Record("scoped-import-probes-preserve-legacy-source",new{sha256=original});
}
var checkedPaths=Directory.GetFiles(Path.Combine(Fixture.Repo,"src/Confectory.Core"),"*.cs").Concat(new[]{Path.Combine(Fixture.Repo,"src/Confectory.Core/Confectory.Core.csproj"),Path.Combine(Fixture.Repo,"Directory.Build.props"),Path.Combine(Fixture.Repo,"tests/Confectory.Tests/Support.cs"),Path.Combine(Fixture.Repo,"tests/probes/blueprint-compatibility/Program.cs"),Path.Combine(Fixture.Repo,"tests/probes/blueprint-compatibility/blueprint-compatibility.csproj")}).Order(StringComparer.Ordinal);var checkedHashes=new JsonObject();foreach(string path in checkedPaths)checkedHashes[Path.GetRelativePath(Fixture.Repo,path).Replace('\\','/')]=Hash(path);
var evidence=new JsonObject{["schema"]=1,["kind"]="owned-fixture-compatibility-investigation",["checkedSourceHashes"]=checkedHashes,["runtimeVersion"]=Environment.Version.ToString(),["profile"]=FeatureBlueprint.Profile,["generator"]=FeatureBlueprint.Generator,["cases"]=rows,["passed"]=rows.Count,["failed"]=0,["policySelected"]=false,["productConversionImplemented"]=false,["implicitEndProfileAdded"]=false};File.WriteAllText(args[0],evidence.ToJsonString(new System.Text.Json.JsonSerializerOptions{WriteIndented=true})+"\n");Console.WriteLine(rows.Count+" compatibility checks passed; no conversion policy selected.");
